import React, { useRef } from "react";

const Ref = () => {
  const myRef = useRef();
  console.log(myRef.current);
  const myVal=(e)=>{
    myRef.current.value=e.target.value
  }
  const getVal=()=>{
    console.log(myRef.current.value)
  }
  return (
    <div>
      <input type="text" ref={myRef}onChange={myVal} />
      <button onClick={getVal}>GEt</button>
    </div>
  );
};

export default Ref;
